    def back(self, steps: int) -> str:
        while steps > 0 and len(self.behind) > 1:
            self.ahead.append(self.behind.pop())
            steps -= 1
        return self.behind[-1]

    def forward(self, steps: int) -> str:
        while steps > 0 and self.ahead:
            self.behind.append(self.ahead.pop())
            steps -= 1
        return self.behind[-1]

